:root { color-scheme: dark; font-family: system-ui, sans-serif; }
* { box-sizing: border-box; }
body { display: grid; min-height: 100vh; margin: 0; place-items: center; padding: 20px; color: #f8fafc; background: #1e293b; }
.calculator { width: min(100%, 340px); padding: 22px; border-radius: 22px; background: #0f172a; box-shadow: 0 24px 70px rgba(0, 0, 0, .35); }
.calculator h1 { margin: 0 0 14px; color: #cbd5e1; font-size: 1rem; }
.screen { display: block; min-height: 88px; padding: 20px 14px; overflow: hidden; border-radius: 13px; background: #020617; font-size: clamp(2rem, 12vw, 2.8rem); text-align: right; word-break: break-all; }
.keys { display: grid; grid-template-columns: repeat(4, 1fr); gap: 10px; margin-top: 16px; }
button { min-width: 48px; min-height: 54px; border: 0; border-radius: 13px; color: #ffffff; background: #334155; font: inherit; font-size: 1.18rem; cursor: pointer; }
button:hover { background: #475569; }
button:focus-visible { outline: 3px solid #fbbf24; outline-offset: 2px; }
.function { color: #fde68a; }
.operator { background: #c2410c; }
.equals { background: #047857; }
.zero { grid-column: span 2; }
@media (prefers-reduced-motion: no-preference) { button:active { transform: scale(.96); } }

const screen = document.querySelector('#screen');
const state = { display: '0', accumulator: null, operator: null, waiting: false };

function render() {
  screen.textContent = state.display;
}

function inputDigit(digit) {
  if (state.waiting || state.display === '错误') {
    state.display = digit;
    state.waiting = false;
  } else {
    state.display = state.display === '0' ? digit : state.display + digit;
  }
}

function inputDecimal() {
  if (state.waiting || state.display === '错误') {
    state.display = '0.';
    state.waiting = false;
  } else if (!state.display.includes('.')) {
    state.display += '.';
  }
}

function applyOperation(left, right, operator) {
  if (operator === '+') return left + right;
  if (operator === '-') return left - right;
  if (operator === '*') return left * right;
  if (operator === '/') return right === 0 ? Number.NaN : left / right;
  return right;
}

function calculateResult() {
  if (state.operator === null || state.accumulator === null) return;
  const result = applyOperation(state.accumulator, Number(state.display), state.operator);
  state.display = Number.isFinite(result) ? String(Number(result.toFixed(10))) : '错误';
  state.accumulator = null;
  state.operator = null;
  state.waiting = true;
}

function chooseOperator(operator) {
  if (state.display === '错误') return;
  if (state.operator !== null && !state.waiting) calculateResult();
  state.accumulator = Number(state.display);
  state.operator = operator;
  state.waiting = true;
}

function press(key) {
  if (/^\d$/.test(key)) inputDigit(key);
  else if (key === '.') inputDecimal();
  else if (['+', '-', '*', '/'].includes(key)) chooseOperator(key);
  else if (key === '=') calculateResult();
  else if (key === 'percent') state.display = String(Number(state.display) / 100);
  else if (key === 'backspace' && !state.waiting) state.display = state.display.length > 1 ? state.display.slice(0, -1) : '0';
  else if (key === 'clear') Object.assign(state, { display: '0', accumulator: null, operator: null, waiting: false });
  render();
}

document.querySelector('.keys').addEventListener('click', event => {
  const button = event.target.closest('button');
  if (button) press(button.dataset.key);
});
document.addEventListener('keydown', event => {
  const aliases = { Enter: '=', Escape: 'clear', Backspace: 'backspace' };
  const key = aliases[event.key] || event.key;
  if (/^\d$/.test(key) || ['.', '+', '-', '*', '/', '=', 'clear', 'backspace'].includes(key)) {
    event.preventDefault();
    press(key);
  }
});
render();
